23: function samplePath(points, w, h, per = 18) {
24:   const src = points.map(p => [p[0] * w, p[1] * h]);
25:   const out = [];
26:   for (let i = 0; i < src.length - 1; i++) {
27:     const p0 = src[Math.max(0, i - 1)];
28:     const p1 = src[i];
29:     const p2 = src[i + 1];
30:     const p3 = src[Math.min(src.length - 1, i + 2)];
31:     for (let s = 0; s < per; s++) {
32:       const t = s / per;
33:       const t2 = t * t;
34:       const t3 = t2 * t;
35:       const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
36:       const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
37:       out.push([x, y]);
38:     }
39:   }
40:   out.push(src[src.length - 1].slice());
41:   return out;
42: }
