216: export function buildBackground(w, h, pathPts, S, dpr = 1, map = {}) {
217:   const theme = getTheme(map.theme);
218:   const decor = map.decor || DECOR;
219:   const basePos = map.base || { x: 0.952, y: 0.60 };
220:   const c = document.createElement('canvas');
221:   c.width = Math.max(1, Math.floor(w * dpr));
222:   c.height = Math.max(1, Math.floor(h * dpr));
223:   const ctx = c.getContext('2d');
224:   ctx.scale(dpr, dpr);
225:   const rng = mulberry32(0x5a7b21 + hashString(map.id || 'tatooine'));
226:   const m = Math.min(w, h);
227: 
228:   // --- base terrain ----------------------------------------------
229:   const bg = ctx.createLinearGradient(0, 0, w * 0.4, h);
230:   bg.addColorStop(0, theme.ground[0]);
231:   bg.addColorStop(0.44, theme.ground[1]);
232:   bg.addColorStop(1, theme.ground[2]);
233:   ctx.fillStyle = bg;
234:   ctx.fillRect(0, 0, w, h);
235: 
236:   // huge soft terrain bands
237:   for (const d of theme.dunes) {
238:     ctx.save();
239:     ctx.translate(d.x * w, d.y * h);
240:     ctx.beginPath();
241:     ctx.ellipse(d.w * w * 0.5, d.h * h * 0.55, d.w * w * 0.5, d.h * h * 0.5, -0.16, 0, TAU);
242:     const g = ctx.createLinearGradient(0, 0, 0, d.h * h);
243:     g.addColorStop(0, d.c);
244:     g.addColorStop(1, 'rgba(255,255,255,0)');
245:     ctx.fillStyle = g;
246:     ctx.fill();
247:     ctx.restore();
248:   }
249: 
250:   // ground character (before the path so the route stays readable)
251:   drawTerrainDetail(ctx, w, h, S, rng, pathPts, theme);
252: 
253:   // wind / terrain ripples
254:   ctx.save();
255:   ctx.lineCap = 'round';
256:   const rippleCount = theme.extra === 'forest' ? 60 : 44;
257:   for (let i = 0; i < rippleCount; i++) {
258:     const x = rng() * w;
259:     const y = rng() * h;
260:     if (distanceToPath(x, y, pathPts) < 44 * S) continue;
261:     const len = (12 + rng() * 46) * S;
262:     const bend = (rng() - 0.5) * 18 * S;
263:     ctx.beginPath();
264:     ctx.moveTo(x, y);
265:     ctx.quadraticCurveTo(x + len * 0.5, y + bend, x + len, y + bend * 0.2);
266:     ctx.strokeStyle = `rgba(${theme.ripple}, ${0.05 + rng() * 0.07})`;
267:     ctx.lineWidth = (0.8 + rng() * 1.4) * S;
268:     ctx.stroke();
269:   }
270:   ctx.restore();
271: 
272:   // speckles / pebbles
273:   for (let i = 0; i < 380; i++) {
274:     const x = rng() * w;
275:     const y = rng() * h;
276:     const s = (0.4 + rng() * 1.7) * S;
277:     ctx.fillStyle = rng() > 0.5
278:       ? `rgba(${theme.speckleDark}, ${0.05 + rng() * 0.15})`
279:       : `rgba(${theme.speckleLight}, ${0.06 + rng() * 0.16})`;
280:     ctx.beginPath();
281:     ctx.arc(x, y, s, 0, TAU);
282:     ctx.fill();
283:   }
284: 
285:   // --- the route ------------------------------------------------
286:   const pw = clamp(34 * S, 28, 54);
287:   ctx.save();
288:   ctx.lineJoin = 'round';
289:   ctx.lineCap = 'round';
290: 
291:   // ambient shadow
292:   tracePoints(ctx, offsetPath(pathPts, 5 * S));
293:   ctx.strokeStyle = theme.pathShadow;
294:   ctx.lineWidth = pw + 17 * S;
295:   ctx.stroke();
296: 
297:   // outer bank
298:   tracePoints(ctx, pathPts);
299:   ctx.strokeStyle = theme.pathBank;
300:   ctx.lineWidth = pw + 9 * S;
301:   ctx.stroke();
302: 
303:   // packed surface
304:   tracePoints(ctx, pathPts);
305:   const pathGrad = ctx.createLinearGradient(0, 0, w, h);
306:   pathGrad.addColorStop(0, theme.pathFill[0]);
307:   pathGrad.addColorStop(0.5, theme.pathFill[1]);
308:   pathGrad.addColorStop(1, theme.pathFill[2]);
309:   ctx.strokeStyle = pathGrad;
310:   ctx.lineWidth = pw;
311:   ctx.stroke();
312: 
313:   // inner highlight
314:   tracePoints(ctx, offsetPath(pathPts, -pw * 0.12));
315:   ctx.strokeStyle = theme.pathHi;
316:   ctx.lineWidth = pw * 0.5;
317:   ctx.stroke();
318: 
319:   // wheel / boot tracks
320:   ctx.setLineDash([12 * S, 20 * S]);
321:   ctx.lineCap = 'butt';
322:   for (const off of [-pw * 0.19, pw * 0.19]) {
323:     tracePoints(ctx, offsetPath(pathPts, off));
324:     ctx.strokeStyle = theme.track;
325:     ctx.lineWidth = 1.8 * S;
326:     ctx.stroke();
327:   }
328:   ctx.setLineDash([]);
329:   ctx.restore();
330: 
331:   // terrain-specific route edges
332:   drawPathEdges(ctx, w, h, S, rng, pathPts, pw, theme);
333: 
334:   // stones lining the path
335:   for (let i = 0; i < pathPts.length; i += 3) {
336:     const p = pathPts[i];
337:     const prev = pathPts[Math.max(0, i - 1)];
338:     const next = pathPts[Math.min(pathPts.length - 1, i + 1)];
339:     let dx = next[0] - prev[0];
340:     let dy = next[1] - prev[1];
341:     const l = Math.hypot(dx, dy) || 1;
342:     dx /= l; dy /= l;
343:     for (const side of [-1, 1]) {
344:       if (rng() > 0.82) continue;
345:       const off = (pw / 2 + 3 + rng() * 7) * side;
346:       const sx = p[0] - dy * off;
347:       const sy = p[1] + dx * off;
348:       drawPebble(ctx, sx, sy, (1.5 + rng() * 3) * S, rng, rng() * TAU, theme);
349:     }
350:   }
351: 
352:   // path edge scrub
353:   for (let i = 0; i < 34; i++) {
354:     const p = pathPts[Math.floor(rng() * pathPts.length)];
355:     if (!p) continue;
356:     const ang = rng() * TAU;
357:     const off = pw * 0.5 + (4 + rng() * 14) * S;
358:     const x = p[0] + Math.cos(ang) * off;
359:     const y = p[1] + Math.sin(ang) * off;
360:     ctx.strokeStyle = `rgba(${theme.scrub}, ${0.14 + rng() * 0.12})`;
361:     ctx.lineWidth = 1.1 * S;
362:     ctx.beginPath();
363:     for (let b = -1; b <= 1; b++) {
364:       ctx.moveTo(x + b * 2 * S, y + 3 * S);
365:       ctx.quadraticCurveTo(x + b * 3 * S, y - 4 * S, x + b * 6 * S, y - 6 * S);
366:     }
367:     ctx.stroke();
368:   }
369: 
370:   // --- army entrance ---------------------------------------------
371:   drawSpawnCave(ctx, w, h, S, rng, theme, pathPts);
372: 
373:   // --- decorations ----------------------------------------------
374:   for (const d of decor) {
375:     const x = d.x * w;
376:     const y = d.y * h;
377:     const r = d.r * m;
378:     drawDecor(ctx, d, x, y, r, S, rng, theme);
379:   }
380: 
381:   // --- relay base -------------------------------------------------
382:   drawRelayBaseStatic(ctx, basePos.x * w, basePos.y * h, m, S, rng, theme);
383: 
384:   // foreground atmosphere (canopy shade, drifting ash glow, etc.)
385:   drawForeground(ctx, w, h, S, rng, theme, pathPts);
386: 
387:   // vignette
388:   const vg = ctx.createRadialGradient(w * 0.5, h * 0.5, Math.min(w, h) * 0.28, w * 0.5, h * 0.5, Math.max(w, h) * 0.82);
389:   vg.addColorStop(0, 'rgba(0,0,0,0)');
390:   vg.addColorStop(1, theme.vignette);
391:   ctx.fillStyle = vg;
392:   ctx.fillRect(0, 0, w, h);
393: 
394:   return c;
395: }
