406: /* Terrain-specific marks drawn under the route. */
407: function drawTerrainDetail(ctx, w, h, S, rng, pathPts, theme) {
408:   if (theme.extra === 'ice') {
409:     // wind-carved sastrugi
410:     ctx.save();
411:     ctx.lineCap = 'round';
412:     for (let i = 0; i < 26; i++) {
413:       const x = rng() * w;
414:       const y = rng() * h;
415:       if (distanceToPath(x, y, pathPts) < 52 * S) continue;
416:       const len = (30 + rng() * 110) * S;
417:       ctx.beginPath();
418:       ctx.moveTo(x, y);
419:       ctx.quadraticCurveTo(x + len * 0.5, y - 5 * S, x + len, y + 2 * S);
420:       ctx.strokeStyle = `rgba(255, 255, 255, ${0.10 + rng() * 0.16})`;
421:       ctx.lineWidth = (1.4 + rng() * 2.4) * S;
422:       ctx.stroke();
423:       ctx.beginPath();
424:       ctx.moveTo(x + 3 * S, y + 3 * S);
425:       ctx.quadraticCurveTo(x + len * 0.5, y - 1 * S, x + len, y + 5 * S);
426:       ctx.strokeStyle = `rgba(76, 116, 138, ${0.06 + rng() * 0.08})`;
427:       ctx.lineWidth = 1.2 * S;
428:       ctx.stroke();
429:     }
430:     ctx.restore();
431:     // frozen melt pools
432:     for (let i = 0; i < 9; i++) {
433:       const x = rng() * w;
434:       const y = rng() * h;
435:       if (distanceToPath(x, y, pathPts) < 70 * S) continue;
436:       const rx = (18 + rng() * 46) * S;
437:       const g = ctx.createRadialGradient(x, y, 0, x, y, rx);
438:       g.addColorStop(0, 'rgba(132, 188, 208, 0.32)');
439:       g.addColorStop(0.7, 'rgba(174, 214, 228, 0.16)');
440:       g.addColorStop(1, 'rgba(174, 214, 228, 0)');
441:       ctx.fillStyle = g;
442:       ctx.beginPath();
443:       ctx.ellipse(x, y, rx, rx * 0.55, rng() * TAU, 0, TAU);
444:       ctx.fill();
445:     }
446:   } else if (theme.extra === 'lava') {
447:     // glowing fissures that never cross the route
448:     for (let i = 0; i < 16; i++) {
449:       let x = rng() * w;
450:       let y = rng() * h;
451:       if (distanceToPath(x, y, pathPts) < 76 * S) continue;
452:       ctx.save();
453:       ctx.lineCap = 'round';
454:       ctx.shadowColor = 'rgba(255, 96, 30, 0.9)';
455:       ctx.shadowBlur = 12 * S;
456:       ctx.beginPath();
457:       ctx.moveTo(x, y);
458:       let px = x;
459:       let py = y;
460:       for (let s = 0; s < 5; s++) {
461:         px += (rng() - 0.3) * 26 * S;
462:         py += (rng() - 0.5) * 22 * S;
463:         ctx.lineTo(px, py);
464:       }
465:       ctx.strokeStyle = 'rgba(255, 118, 34, 0.55)';
466:       ctx.lineWidth = (1.4 + rng() * 1.8) * S;
467:       ctx.stroke();
468:       ctx.strokeStyle = 'rgba(255, 226, 150, 0.85)';
469:       ctx.lineWidth = 0.7 * S;
470:       ctx.stroke();
471:       ctx.restore();
472:     }
473:     // scorched basalt patches
474:     for (let i = 0; i < 40; i++) {
475:       const x = rng() * w;
476:       const y = rng() * h;
477:       if (distanceToPath(x, y, pathPts) < 40 * S) continue;
478:       ctx.fillStyle = `rgba(12, 7, 6, ${0.10 + rng() * 0.18})`;
479:       ctx.beginPath();
480:       ctx.ellipse(x, y, (8 + rng() * 30) * S, (5 + rng() * 16) * S, rng() * TAU, 0, TAU);
481:       ctx.fill();
482:     }
483:   } else if (theme.extra === 'forest') {
484:     // leaf litter and mossy patches
485:     for (let i = 0; i < 220; i++) {
486:       const x = rng() * w;
487:       const y = rng() * h;
488:       const c = rng() > 0.5 ? '110, 140, 60' : '60, 88, 38';
489:       ctx.fillStyle = `rgba(${c}, ${0.06 + rng() * 0.16})`;
490:       ctx.beginPath();
491:       ctx.ellipse(x, y, (1.2 + rng() * 3.4) * S, (0.8 + rng() * 1.6) * S, rng() * TAU, 0, TAU);
492:       ctx.fill();
493:     }
494:     for (let i = 0; i < 18; i++) {
495:       const x = rng() * w;
496:       const y = rng() * h;
497:       if (distanceToPath(x, y, pathPts) < 46 * S) continue;
498:       const rx = (16 + rng() * 42) * S;
499:       ctx.fillStyle = `rgba(120, 156, 70, ${0.05 + rng() * 0.09})`;
500:       ctx.beginPath();
501:       ctx.ellipse(x, y, rx, rx * 0.5, rng() * TAU, 0, TAU);
502:       ctx.fill();
503:     }
504:   }
505: }
