507: /* Extra edges and glow applied directly around the route. */
508: function drawPathEdges(ctx, w, h, S, rng, pathPts, pw, theme) {
509:   if (theme.extra === 'lava') {
510:     ctx.save();
511:     ctx.lineJoin = 'round';
512:     ctx.lineCap = 'round';
513:     ctx.shadowColor = 'rgba(255, 98, 26, 0.85)';
514:     ctx.shadowBlur = 10 * S;
515:     for (const side of [-1, 1]) {
516:       tracePoints(ctx, offsetPath(pathPts, side * (pw * 0.5 + 1.5 * S)));
517:       ctx.strokeStyle = 'rgba(255, 132, 42, 0.65)';
518:       ctx.lineWidth = 1.6 * S;
519:       ctx.stroke();
520:     }
521:     ctx.restore();
522:     // molten seams
523:     ctx.save();
524:     ctx.setLineDash([7 * S, 15 * S]);
525:     tracePoints(ctx, offsetPath(pathPts, pw * 0.27));
526:     ctx.strokeStyle = 'rgba(255, 170, 80, 0.4)';
527:     ctx.lineWidth = 1 * S;
528:     ctx.stroke();
529:     ctx.restore();
530:   } else if (theme.extra === 'ice') {
531:     ctx.save();
532:     for (const side of [-1, 1]) {
533:       tracePoints(ctx, offsetPath(pathPts, side * (pw * 0.5 + 2 * S)));
534:       ctx.strokeStyle = 'rgba(255, 255, 255, 0.42)';
535:       ctx.lineWidth = 2.2 * S;
536:       ctx.stroke();
537:       tracePoints(ctx, offsetPath(pathPts, side * (pw * 0.5 + 5 * S)));
538:       ctx.strokeStyle = 'rgba(74, 118, 140, 0.18)';
539:       ctx.lineWidth = 1.2 * S;
540:       ctx.stroke();
541:     }
542:     ctx.restore();
543:     // glinting ice chips
544:     for (let i = 0; i < 26; i++) {
545:       const p = pathPts[Math.floor(rng() * pathPts.length)];
546:       if (!p) continue;
547:       const off = (pw * 0.5 + (3 + rng() * 12) * S) * (rng() > 0.5 ? 1 : -1);
548:       const x = p[0] + off;
549:       const y = p[1] + (rng() - 0.5) * 10 * S;
550:       ctx.fillStyle = `rgba(255, 255, 255, ${0.3 + rng() * 0.5})`;
551:       ctx.beginPath();
552:       ctx.arc(x, y, (0.6 + rng() * 1.2) * S, 0, TAU);
553:       ctx.fill();
554:     }
555:   } else if (theme.extra === 'forest') {
556:     ctx.save();
557:     for (const side of [-1, 1]) {
558:       tracePoints(ctx, offsetPath(pathPts, side * (pw * 0.5 + 2 * S)));
559:       ctx.strokeStyle = 'rgba(48, 66, 30, 0.45)';
560:       ctx.lineWidth = 2 * S;
561:       ctx.stroke();
562:     }
563:     ctx.restore();
564:     for (let i = 0; i < 60; i++) {
565:       const p = pathPts[Math.floor(rng() * pathPts.length)];
566:       if (!p) continue;
567:       const off = (pw * 0.5 + (2 + rng() * 9) * S) * (rng() > 0.5 ? 1 : -1);
568:       ctx.fillStyle = `rgba(${rng() > 0.5 ? '120, 158, 72' : '88, 66, 38'}, ${0.18 + rng() * 0.22})`;
569:       ctx.beginPath();
570:       ctx.ellipse(p[0] + off, p[1] + (rng() - 0.5) * 8 * S, (1 + rng() * 2.4) * S, (0.6 + rng() * 1.1) * S, rng() * TAU, 0, TAU);
571:       ctx.fill();
572:     }
573:   }
574: }
