576: /* Arcade foreground layers: canopy shade, snow haze, heat shimmer. */
577: function drawForeground(ctx, w, h, S, rng, theme, pathPts) {
578:   if (theme.extra === 'forest') {
579:     ctx.save();
580:     for (let i = 0; i < 7; i++) {
581:       const x = rng() * w;
582:       const y = rng() * h;
583:       if (distanceToPath(x, y, pathPts) < 70 * S) continue;
584:       const rx = (60 + rng() * 150) * S;
585:       ctx.fillStyle = `rgba(4, 16, 6, ${0.06 + rng() * 0.10})`;
586:       ctx.beginPath();
587:       ctx.ellipse(x, y, rx, rx * 0.55, rng() * TAU, 0, TAU);
588:       ctx.fill();
589:     }
590:     ctx.restore();
591:   } else if (theme.extra === 'ice') {
592:     ctx.save();
593:     for (let i = 0; i < 5; i++) {
594:       const x = rng() * w;
595:       const y = rng() * h;
596:       const g = ctx.createRadialGradient(x, y, 0, x, y, (70 + rng() * 100) * S);
597:       g.addColorStop(0, 'rgba(255, 255, 255, 0.10)');
598:       g.addColorStop(1, 'rgba(255, 255, 255, 0)');
599:       ctx.fillStyle = g;
600:       ctx.fillRect(x - 160 * S, y - 160 * S, 320 * S, 320 * S);
601:     }
602:     ctx.restore();
603:   } else if (theme.extra === 'lava') {
604:     ctx.save();
605:     for (let i = 0; i < 4; i++) {
606:       const x = rng() * w;
607:       const y = rng() * h;
608:       const g = ctx.createRadialGradient(x, y, 0, x, y, (90 + rng() * 120) * S);
609:       g.addColorStop(0, 'rgba(255, 96, 30, 0.10)');
610:       g.addColorStop(1, 'rgba(255, 96, 30, 0)');
611:       ctx.fillStyle = g;
612:       ctx.fillRect(x - 200 * S, y - 200 * S, 400 * S, 400 * S);
613:     }
614:     ctx.restore();
615:   }
616: }
