/* —— Tatooine · womp rat ——————————————————————————————
   A low, hunched desert rodent seen from above: scruffy grey-brown
   fur, oversized hind paws, and a long bare tail that whips behind it. */
function drawWompratBody(ctx, e, time) {
  const p = e.phase || 0;
  const stride = Math.sin(time * 17 + p);
  const strideB = Math.sin(time * 17 + p + Math.PI * 0.7);
  const tailWave = Math.sin(time * 7.4 + p);
  const tailWave2 = Math.sin(time * 7.4 + p - 0.9);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Long bare tail, tapering in three segments.
  ctx.strokeStyle = '#a97c68';
  ctx.lineWidth = 2.1;
  ctx.beginPath();
  ctx.moveTo(-7.4, 0.2);
  ctx.quadraticCurveTo(-12.5, tailWave * 1.4, -17.5, tailWave * 3.2);
  ctx.stroke();
  ctx.lineWidth = 1.45;
  ctx.beginPath();
  ctx.moveTo(-17.2, tailWave * 3.1);
  ctx.quadraticCurveTo(-21.5, tailWave * 4.2, -25.2, tailWave2 * 5.3);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(224, 178, 150, 0.45)';
  ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.moveTo(-8.2, 0.15);
  ctx.quadraticCurveTo(-13, tailWave * 1.4 - 0.3, -18, tailWave * 3.1 - 0.2);
  ctx.stroke();

  // Four splayed paws, hind legs larger and pushing off.
  const legs = [
    { x: 3.6, y: -3.2, ex: 7.6, ey: -7.4, fx: 9.2, fy: -10.1, s: stride },
    { x: 3.6, y: 3.2, ex: 7.6, ey: 7.4, fx: 9.2, fy: 10.1, s: -stride },
    { x: -5.8, y: -3.6, ex: -10.1, ey: -8.0, fx: -11.6, fy: -11.2, s: -strideB },
    { x: -5.8, y: 3.6, ex: -10.1, ey: 8.0, fx: -11.6, fy: 11.2, s: strideB },
  ];
  for (const leg of legs) {
    const dx = leg.s * 1.15;
    ctx.strokeStyle = '#705846';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.ex + dx * 0.6, leg.ey);
    ctx.lineTo(leg.fx + dx, leg.fy);
    ctx.stroke();
    // paw + tiny toes
    ctx.fillStyle = '#5e4a3b';
    ctx.beginPath();
    ctx.ellipse(leg.fx + dx, leg.fy, 1.65, 1.15, Math.atan2(leg.fy, leg.fx), 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#c9ae94';
    ctx.lineWidth = 0.45;
    for (let t = -1; t <= 1; t++) {
      ctx.beginPath();
      ctx.moveTo(leg.fx + dx, leg.fy);
      ctx.lineTo(leg.fx + dx + Math.cos(Math.atan2(leg.fy, leg.fx)) * 1.9, leg.fy + Math.sin(Math.atan2(leg.fy, leg.fx)) * 1.9 + t * 1.05);
      ctx.stroke();
    }
  }

  // Hunched, pear-shaped torso.
  const body = ctx.createLinearGradient(-6, -7, 5, 7);
  body.addColorStop(0, '#b59a7c');
  body.addColorStop(0.48, '#90765f');
  body.addColorStop(1, '#6b5543');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-9.2, 0);
  ctx.bezierCurveTo(-9.4, -4.6, -4.6, -6.3, 0.4, -5.7);
  ctx.bezierCurveTo(4.4, -5.3, 6.8, -3.7, 7.3, -1.7);
  ctx.lineTo(7.3, 1.7);
  ctx.bezierCurveTo(6.8, 3.7, 4.4, 5.3, 0.4, 5.7);
  ctx.bezierCurveTo(-4.6, 6.3, -9.4, 4.6, -9.2, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(68, 49, 36, 0.55)';
  ctx.lineWidth = 0.65;
  ctx.stroke();

  // Scruffy fur tufts and a pale spine highlight.
  ctx.strokeStyle = 'rgba(212, 190, 161, 0.55)';
  ctx.lineWidth = 0.5;
  for (let i = 0; i < 12; i++) {
    const a = -0.95 + i * 0.17;
    const bx = Math.cos(a) * 8.4;
    const by = Math.sin(a) * 4.9;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(bx + Math.cos(a) * 1.8, by + Math.sin(a) * 1.5);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(214, 193, 164, 0.4)';
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(-6.4, 0.1);
  ctx.quadraticCurveTo(-1, -0.9, 4.8, 0);
  ctx.stroke();

  // Shoulder hump.
  ctx.fillStyle = 'rgba(128, 101, 78, 0.9)';
  ctx.beginPath();
  ctx.ellipse(2.7, -0.2, 3.6, 4.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(187, 161, 128, 0.32)';
  ctx.beginPath();
  ctx.ellipse(2.1, -1.3, 2.2, 2.4, 0, 0, TAU);
  ctx.fill();

  // Head: narrow wedge, round ears, beaded eyes, whiskers and incisors.
  const hg = ctx.createLinearGradient(6, -3.4, 15, 3.4);
  hg.addColorStop(0, '#a78b6e');
  hg.addColorStop(0.55, '#8b7058');
  hg.addColorStop(1, '#6e5745');
  ctx.fillStyle = hg;
  ctx.beginPath();
  ctx.moveTo(6.1, -3.5);
  ctx.lineTo(11.2, -2.9);
  ctx.quadraticCurveTo(14.7, -1.9, 15.2, 0);
  ctx.quadraticCurveTo(14.7, 1.9, 11.2, 2.9);
  ctx.lineTo(6.1, 3.5);
  ctx.quadraticCurveTo(5.2, 0, 6.1, -3.5);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#57432f';
  ctx.lineWidth = 0.7;
  ctx.stroke();

  // ears
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#7d634d';
    ctx.beginPath();
    ctx.ellipse(8.1, side * 3.3, 1.9, 1.25, side * 0.5, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(205, 157, 137, 0.75)';
    ctx.beginPath();
    ctx.ellipse(8.2, side * 3.25, 1.05, 0.62, side * 0.5, 0, TAU);
    ctx.fill();
  }

  // eyes
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#211711';
    ctx.beginPath();
    ctx.arc(11.45, side * 1.45, 0.72, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 205, 118, 0.9)';
    ctx.beginPath();
    ctx.arc(11.58, side * 1.42, 0.26, 0, TAU);
    ctx.fill();
  }

  // nose and whiskers
  ctx.fillStyle = '#c98a78';
  ctx.beginPath();
  ctx.ellipse(14.9, 0, 0.62, 0.5, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(235, 214, 185, 0.55)';
  ctx.lineWidth = 0.28;
  for (const side of [-1, 1]) {
    for (let i = -1; i <= 1; i++) {
      ctx.beginPath();
      ctx.moveTo(13.2, side * 0.75);
      ctx.quadraticCurveTo(15, side * (1.7 + i * 0.55), 16.8 + Math.abs(i) * 0.4, side * (2.4 + i * 0.9));
      ctx.stroke();
    }
  }
  // two small incisors
  ctx.fillStyle = '#f0e3c8';
  ctx.beginPath();
  ctx.moveTo(14.3, -0.62);
  ctx.lineTo(15.35, -0.2);
  ctx.lineTo(14.3, 0.05);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(14.3, 0.62);
  ctx.lineTo(15.35, 0.2);
  ctx.lineTo(14.3, -0.05);
  ctx.closePath();
  ctx.fill();

  // quick little breath / whisker twitch
  const twitch = Math.sin(time * 13 + p) * 0.22;
  ctx.strokeStyle = 'rgba(230, 210, 180, 0.4)';
  ctx.lineWidth = 0.25;
  ctx.beginPath();
  ctx.moveTo(13.4, -0.4);
  ctx.lineTo(16.2, -2.2 + twitch);
  ctx.moveTo(13.4, 0.4);
  ctx.lineTo(16.2, 2.2 - twitch);
  ctx.stroke();
}

/* —— Tatooine · bantha ————————————————————————————————
   A mountain of dark shaggy fur on four column legs. The huge
   ivory horns sweep out from a low, bearded head. */
function drawBanthaBody(ctx, e, time) {
  const p = e.phase || 0;
  const gait = Math.sin(time * 4.6 + p);
  const gaitB = Math.sin(time * 4.6 + p + 2.1);
  const tailSway = Math.sin(time * 2.3 + p);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Tufted tail.
  ctx.strokeStyle = '#3f2a1d';
  ctx.lineWidth = 2.3;
  ctx.beginPath();
  ctx.moveTo(-16.5, 0);
  ctx.quadraticCurveTo(-22.5, tailSway * 1.4, -26.5, tailSway * 2.3);
  ctx.stroke();
  ctx.fillStyle = '#4a3020';
  ctx.beginPath();
  ctx.ellipse(-27.6, tailSway * 2.5, 3.4, 2.1, tailSway * 0.4, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(144, 105, 72, 0.5)';
  ctx.lineWidth = 0.5;
  for (let i = 0; i < 5; i++) {
    const a = -0.8 + i * 0.4;
    ctx.beginPath();
    ctx.moveTo(-27.5, tailSway * 2.5);
    ctx.lineTo(-27.5 + Math.cos(a) * 4.6, tailSway * 2.5 + Math.sin(a) * 3.4);
    ctx.stroke();
  }

  // Four stout legs with broad hooves.
  const legs = [
    { x: 9.5, y: -8.0, kx: 12.2, ky: -14.4, fx: 12.8, fy: -19.6, s: gait },
    { x: 9.5, y: 8.0, kx: 12.2, ky: 14.4, fx: 12.8, fy: 19.6, s: -gait },
    { x: -10.5, y: -8.0, kx: -13.0, ky: -14.2, fx: -13.6, fy: -19.2, s: -gaitB },
    { x: -10.5, y: 8.0, kx: -13.0, ky: 14.2, fx: -13.6, fy: 19.2, s: gaitB },
  ];
  for (const leg of legs) {
    const swing = leg.s * 1.8;
    ctx.strokeStyle = '#39261a';
    ctx.lineWidth = 5.4;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.kx + swing * 0.35, leg.ky);
    ctx.lineTo(leg.fx + swing, leg.fy);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(123, 86, 58, 0.7)';
    ctx.lineWidth = 1.7;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.kx + swing * 0.35, leg.ky);
    ctx.stroke();
    // hoof
    ctx.fillStyle = '#241710';
    ctx.beginPath();
    ctx.ellipse(leg.fx + swing, leg.fy, 3.2, 2.0, Math.atan2(leg.fy, leg.fx), 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(132, 102, 74, 0.55)';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(leg.fx + swing - 1.2, leg.fy);
    ctx.lineTo(leg.fx + swing + 1.2, leg.fy);
    ctx.stroke();
  }

  // Massive shaggy barrel body.
  const body = ctx.createLinearGradient(-8, -12, 14, 12);
  body.addColorStop(0, '#5d4029');
  body.addColorStop(0.42, '#46301f');
  body.addColorStop(1, '#2d1d13');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-16.5, 0);
  ctx.bezierCurveTo(-16.5, -8.2, -10.6, -12.0, -1.8, -12.2);
  ctx.bezierCurveTo(7.0, -12.4, 13.6, -9.4, 15.4, -4.2);
  ctx.bezierCurveTo(16.6, -0.6, 16.6, 0.6, 15.4, 4.2);
  ctx.bezierCurveTo(13.6, 9.4, 7.0, 12.4, -1.8, 12.2);
  ctx.bezierCurveTo(-10.6, 12.0, -16.5, 8.2, -16.5, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#1c110a';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // Shaggy fur fringe all the way around the silhouette.
  const furCols = ['rgba(118, 82, 53, 0.9)', 'rgba(83, 56, 36, 0.95)', 'rgba(155, 115, 78, 0.55)'];
  for (let i = 0; i < 38; i++) {
    const a = (i / 38) * TAU;
    const rx = 15.4;
    const ry = 11.3;
    const bx = Math.cos(a) * rx;
    const by = Math.sin(a) * ry;
    const len = 2.4 + ((i * 7) % 5) * 0.55;
    ctx.strokeStyle = furCols[i % furCols.length];
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    ctx.moveTo(bx * 0.92, by * 0.92);
    ctx.lineTo(bx + Math.cos(a + 0.12) * len, by + Math.sin(a + 0.12) * len);
    ctx.stroke();
  }
  // inner coat strokes
  ctx.lineWidth = 0.7;
  for (let i = 0; i < 22; i++) {
    const a = (i / 22) * TAU;
    const bx = Math.cos(a) * 11.5;
    const by = Math.sin(a) * 8.0;
    ctx.strokeStyle = i % 3 === 0 ? 'rgba(164, 126, 88, 0.34)' : 'rgba(35, 22, 14, 0.44)';
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(bx + Math.cos(a + 0.28) * 2.3, by + Math.sin(a + 0.28) * 1.9);
    ctx.stroke();
  }

  // Back ridge and shoulder hump.
  ctx.fillStyle = 'rgba(30, 19, 12, 0.55)';
  ctx.beginPath();
  ctx.ellipse(1.4, 0, 8.8, 4.1, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(146, 107, 72, 0.32)';
  ctx.beginPath();
  ctx.ellipse(-0.4, -1.4, 6.8, 2.4, 0, 0, TAU);
  ctx.fill();

  // Saddle blanket and harness: a working bantha, not a wild one.
  ctx.save();
  ctx.fillStyle = '#6f3325';
  roundRect(ctx, -6.4, -5.4, 11.2, 10.8, 2.4);
  ctx.fill();
  ctx.strokeStyle = 'rgba(217, 164, 92, 0.8)';
  ctx.lineWidth = 0.8;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(230, 184, 112, 0.55)';
  ctx.lineWidth = 0.45;
  for (let i = -4.4; i <= 3.5; i += 2.6) {
    ctx.beginPath();
    ctx.moveTo(i, -4.3);
    ctx.lineTo(i, 4.3);
    ctx.stroke();
  }
  ctx.fillStyle = '#c9a56a';
  for (const sy of [-4.7, 4.7]) {
    for (let i = -5.2; i <= 3.4; i += 2.8) {
      ctx.beginPath();
      ctx.arc(i, sy, 0.52, 0, TAU);
      ctx.fill();
    }
  }
  ctx.strokeStyle = '#332014';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(4.8, -5.8);
  ctx.lineTo(7.8, -9.2);
  ctx.moveTo(4.8, 5.8);
  ctx.lineTo(7.8, 9.2);
  ctx.stroke();
  ctx.restore();

  // Shaggy neck mane.
  ctx.fillStyle = '#3b2618';
  ctx.beginPath();
  ctx.ellipse(14.2, 0, 5.6, 8.4, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(137, 98, 64, 0.7)';
  ctx.lineWidth = 0.8;
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU;
    ctx.beginPath();
    ctx.moveTo(14.2 + Math.cos(a) * 3.1, Math.sin(a) * 5.0);
    ctx.lineTo(14.2 + Math.cos(a + 0.2) * 5.9, Math.sin(a + 0.2) * 8.8);
    ctx.stroke();
  }

  // Head and muzzle.
  const hg = ctx.createLinearGradient(16, -5, 25, 5);
  hg.addColorStop(0, '#62442c');
  hg.addColorStop(0.5, '#4a3220');
  hg.addColorStop(1, '#2f1f14');
  ctx.fillStyle = hg;
  ctx.beginPath();
  ctx.moveTo(16.4, -5.1);
  ctx.quadraticCurveTo(20.8, -6.0, 23.6, -4.2);
  ctx.lineTo(25.9, -1.8);
  ctx.quadraticCurveTo(26.7, 0, 25.9, 1.8);
  ctx.lineTo(23.6, 4.2);
  ctx.quadraticCurveTo(20.8, 6.0, 16.4, 5.1);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#24160d';
  ctx.lineWidth = 0.9;
  ctx.stroke();
  // muzzle highlight, nostrils, eyes
  ctx.fillStyle = 'rgba(164, 126, 88, 0.35)';
  ctx.beginPath();
  ctx.ellipse(22.6, 0, 2.8, 3.4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#170e09';
  ctx.beginPath();
  ctx.ellipse(25.3, -1.08, 0.72, 0.42, 0, 0, TAU);
  ctx.ellipse(25.3, 1.08, 0.72, 0.42, 0, 0, TAU);
  ctx.fill();
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#0f0906';
    ctx.beginPath();
    ctx.arc(21.4, side * 3.0, 0.85, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 196, 104, 0.85)';
    ctx.beginPath();
    ctx.arc(21.55, side * 3.0, 0.28, 0, TAU);
    ctx.fill();
  }

  // Enormous curved ivory horns. One path mirrored on each side.
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.scale(1, side);
    const horn = ctx.createLinearGradient(16, -4, 24, -19);
    horn.addColorStop(0, '#d7c19a');
    horn.addColorStop(0.45, '#e8d7b5');
    horn.addColorStop(1, '#a98d64');
    ctx.fillStyle = horn;
    ctx.beginPath();
    ctx.moveTo(17.0, -3.6);
    ctx.bezierCurveTo(24.0, -6.8, 28.4, -13.0, 24.4, -18.6);
    ctx.bezierCurveTo(21.4, -22.8, 14.2, -23.0, 10.6, -19.8);
    ctx.bezierCurveTo(15.4, -20.2, 20.0, -17.2, 21.0, -12.4);
    ctx.bezierCurveTo(21.7, -9.0, 20.0, -6.0, 17.0, -3.6);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#6f5636';
    ctx.lineWidth = 0.75;
    ctx.stroke();
    // growth rings
    ctx.strokeStyle = 'rgba(112, 86, 52, 0.42)';
    ctx.lineWidth = 0.45;
    for (let i = 0; i < 4; i++) {
      const t = 0.16 + i * 0.17;
      ctx.beginPath();
      ctx.moveTo(17.9 + t * 2.2, -4.2 - t * 4.6);
      ctx.quadraticCurveTo(20.0 + t * 3.0, -8.0 - t * 5.4, 22.6 + t * 0.4, -14.0 - t * 5.2);
      ctx.stroke();
    }
    // polished tip highlight
    ctx.strokeStyle = 'rgba(255, 246, 218, 0.55)';
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(12.4, -20.4);
    ctx.quadraticCurveTo(16.8, -21.4, 20.4, -19.8);
    ctx.stroke();
    ctx.restore();
  }

  // Little tusk pair and chin beard.
  ctx.fillStyle = '#dbc9a6';
  ctx.beginPath();
  ctx.moveTo(24.0, -2.9);
  ctx.lineTo(26.6, -3.8);
  ctx.lineTo(25.0, -2.0);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(24.0, 2.9);
  ctx.lineTo(26.6, 3.8);
  ctx.lineTo(25.0, 2.0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(27, 17, 10, 0.85)';
  ctx.lineWidth = 1.1;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(23.4, i * 2.0);
    ctx.quadraticCurveTo(25.4, i * 3.6, 26.0, i * 5.0);
    ctx.stroke();
  }
}

/* —— Tatooine · krayt dragon ————————————————————————————
   The final-boss silhouette: a long tan armored reptile, wide
   shoulders, splayed claws, a horned skull, and a sweeping spiked tail. */
function drawKraytBody(ctx, e, time) {
  const p = e.phase || 0;
  const tailSway = Math.sin(time * 2.7 + p);
  const tailSwayB = Math.sin(time * 2.7 + p - 0.8);
  const gait = Math.sin(time * 3.6 + p);
  const gaitB = Math.sin(time * 3.6 + p + Math.PI * 0.75);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Long sweeping tail, thick at the hips and whip-thin at the tip.
  const tail = ctx.createLinearGradient(-10, -5, -40, 5);
  tail.addColorStop(0, '#b28a58');
  tail.addColorStop(0.6, '#a17a4d');
  tail.addColorStop(1, '#8b6742');
  ctx.fillStyle = tail;
  ctx.beginPath();
  ctx.moveTo(-9.0, -7.4);
  ctx.bezierCurveTo(-18.0, -8.4, -28.0, -6.0 + tailSway * 2.2, -41.0, tailSwayB * 5.4);
  ctx.bezierCurveTo(-34.0, 0.4 + tailSwayB * 3.0, -25.0, 5.0 + tailSway * 2.0, -15.0, 7.0);
  ctx.bezierCurveTo(-11.6, 7.8, -9.0, 7.4, -9.0, 7.4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5e4128';
  ctx.lineWidth = 0.9;
  ctx.stroke();

  // Tail scutes and dorsal spikes.
  for (let i = 0; i < 7; i++) {
    const t = i / 6;
    const tx = -14 - t * 23;
    const ty = tailSwayB * (t * 3.6) + Math.sin(t * 2.4) * 1.0;
    const size = 2.2 - t * 1.4;
    ctx.fillStyle = i % 2 ? '#c6a06a' : '#b48a55';
    ctx.beginPath();
    ctx.moveTo(tx + size * 0.7, ty);
    ctx.lineTo(tx - size * 0.2, ty - size * 1.45);
    ctx.lineTo(tx - size * 0.9, ty);
    ctx.lineTo(tx - size * 0.2, ty + size * 1.45);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(75, 51, 30, 0.7)';
    ctx.lineWidth = 0.35;
    ctx.stroke();
  }

  // Splayed clawed limbs.
  const legs = [
    { x: 11.5, y: -8.0, kx: 18.4, ky: -17.0, fx: 23.0, fy: -22.6, s: gait, front: true },
    { x: 11.5, y: 8.0, kx: 18.4, ky: 17.0, fx: 23.0, fy: 22.6, s: -gait, front: true },
    { x: -9.5, y: -8.4, kx: -15.4, ky: -16.8, fx: -19.8, fy: -22.2, s: -gaitB, front: false },
    { x: -9.5, y: 8.4, kx: -15.4, ky: 16.8, fx: -19.8, fy: 22.2, s: gaitB, front: false },
  ];
  for (const leg of legs) {
    const swing = leg.s * 1.5;
    ctx.strokeStyle = '#7b5a39';
    ctx.lineWidth = leg.front ? 6.2 : 5.4;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.quadraticCurveTo(leg.kx + swing * 0.4, leg.ky, leg.fx + swing, leg.fy);
    ctx.stroke();
    // muscle highlight
    ctx.strokeStyle = 'rgba(213, 177, 125, 0.45)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.quadraticCurveTo(leg.kx + swing * 0.4, leg.ky, leg.fx + swing, leg.fy);
    ctx.stroke();
    // three ivory claws
    const ang = Math.atan2(leg.fy, leg.fx);
    for (let c = -1; c <= 1; c++) {
      const a = ang + c * 0.24;
      ctx.fillStyle = '#ead9b6';
      ctx.beginPath();
      ctx.moveTo(leg.fx + swing, leg.fy);
      ctx.lineTo(leg.fx + swing + Math.cos(a) * 4.3, leg.fy + Math.sin(a) * 4.3);
      ctx.lineTo(leg.fx + swing + Math.cos(a + 0.16) * 2.5, leg.fy + Math.sin(a + 0.16) * 2.5);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#87683f';
      ctx.lineWidth = 0.35;
      ctx.stroke();
    }
  }

  // Broad, armor-plated body.
  const body = ctx.createLinearGradient(-6, -14, 12, 14);
  body.addColorStop(0, '#d9b985');
  body.addColorStop(0.42, '#c39c68');
  body.addColorStop(1, '#927044');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-11.0, -8.6);
  ctx.bezierCurveTo(-2.0, -14.4, 11.0, -15.0, 16.0, -10.2);
  ctx.bezierCurveTo(19.2, -7.0, 19.2, 7.0, 16.0, 10.2);
  ctx.bezierCurveTo(11.0, 15.0, -2.0, 14.4, -11.0, 8.6);
  ctx.bezierCurveTo(-13.4, 5.6, -13.4, -5.6, -11.0, -8.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5b3f26';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // Armor bands / scute seams across the back.
  ctx.strokeStyle = 'rgba(106, 74, 43, 0.6)';
  ctx.lineWidth = 0.9;
  for (let i = 0; i < 6; i++) {
    const x = -7.0 + i * 3.8;
    const span = 8.8 - Math.abs(x) * 0.16;
    ctx.beginPath();
    ctx.moveTo(x, -span);
    ctx.quadraticCurveTo(x + 2.2, 0, x, span);
    ctx.stroke();
  }
  // Central row of raised scutes.
  for (let i = 0; i < 6; i++) {
    const x = -7.2 + i * 4.2;
    const w = 2.4 - i * 0.12;
    ctx.fillStyle = i % 2 ? '#d4b17c' : '#c8a26c';
    ctx.beginPath();
    ctx.moveTo(x + w, 0);
    ctx.lineTo(x - w * 0.4, -4.0 + i * 0.2);
