import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

mkdirSync('screenshots', { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', e => console.error('PAGEERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.error('CONSOLE:', m.text()); });
await page.goto('http://localhost:8000/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/01-start.jpg', type: 'jpeg', quality: 82 });

await page.locator('#playBtn').click();
await page.waitForTimeout(500);
await page.locator('#chooseMapBtn').click();
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/02-map.jpg', type: 'jpeg', quality: 82 });

await page.evaluate(() => {
  document.querySelectorAll('.screen').forEach(el => el.classList.add('hidden'));
  const g = window.__game;
  g.setMap('tatooine');
  g.started = true;
  g.begin();
  g.waveNumber = 6;
  g.phase = 'wave';
  g.waveActive = true;
  g.waveTotal = 12;
  g.credits = 1600;
  g.enemies = [];
  const spawn = (type, t) => {
    const def = type === 'womprat' ? { hp: 10, speed: 98 } : type === 'bantha' ? { hp: 150, speed: 37 } : { hp: 900, speed: 27 };
    g.spawnEnemy({ type, hp: def.hp, speed: def.speed, delay: 0 });
    const e = g.enemies[g.enemies.length - 1];
    e.t = t;
    g.positionEnemy(e);
  };
  spawn('womprat', 0.18);
  spawn('womprat', 0.22);
  spawn('womprat', 0.26);
  spawn('bantha', 0.34);
  spawn('womprat', 0.40);
  spawn('bantha', 0.46);
  spawn('womprat', 0.52);
  spawn('krayt', 0.62);
  spawn('bantha', 0.70);
  // a few defence towers so the battlefield reads as a game
  g.placeTower('scout', 0.20, 0.55);
  g.placeTower('rocket', 0.42, 0.52);
  g.placeTower('laser', 0.55, 0.60);
  g.placeTower('bounty', 0.66, 0.50);
  g.selected = null;
});
await page.waitForTimeout(1200);
await page.screenshot({ path: 'screenshots/03-battle.jpg', type: 'jpeg', quality: 84 });

// boss close-up: zoom onto the krayt via canvas clipping is not possible, so frame a boss wave
await page.evaluate(() => {
  const g = window.__game;
  g.enemies = [];
  g.waveNumber = 25;
  g.phase = 'wave';
  g.waveActive = true;
  g.spawnEnemy({ type: 'krayt', hp: 2400, speed: 27, delay: 0 });
  const boss = g.enemies[g.enemies.length - 1];
  boss.t = 0.47;
  g.positionEnemy(boss);
  for (let i = 0; i < 3; i++) {
    g.spawnEnemy({ type: 'bantha', hp: 420, speed: 37, delay: 0 });
    const e = g.enemies[g.enemies.length - 1];
    e.t = 0.35 + i * 0.08;
    g.positionEnemy(e);
  }
  for (let i = 0; i < 5; i++) {
    g.spawnEnemy({ type: 'womprat', hp: 24, speed: 98, delay: 0 });
    const e = g.enemies[g.enemies.length - 1];
    e.t = 0.64 + i * 0.035;
    g.positionEnemy(e);
  }
});
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/04-boss.jpg', type: 'jpeg', quality: 84 });

await browser.close();
console.log('saved screenshots');

import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

mkdirSync('screenshots', { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 }, deviceScaleFactor: 1 });
page.on('pageerror', e => console.error('PAGEERROR:', e.message));
await page.goto('http://localhost:8000/', { waitUntil: 'load' });
await page.waitForTimeout(700);
await page.evaluate(async () => {
  document.querySelectorAll('.screen').forEach(el => el.classList.add('hidden'));
  const { drawEnemy } = await import('/src/art.js');
  const wrap = document.createElement('div');
  wrap.style.cssText = 'position:fixed;inset:0;z-index:99999;background:linear-gradient(135deg,#d8ad72,#bf8e58);display:flex;align-items:center;justify-content:center;gap:10px';
  const c = document.createElement('canvas');
  c.width = 1260; c.height = 620;
  c.style.width = '1260px'; c.style.height = '620px';
  wrap.appendChild(c);
  document.body.appendChild(wrap);
  const ctx = c.getContext('2d');
  const defs = [
    ['womprat', 190, 260, 3.2],
    ['bantha', 620, 260, 3.2],
    ['krayt', 1010, 300, 2.7],
  ];
  for (const [type, x, y, S] of defs) {
    const radius = type === 'womprat' ? 8.5 : type === 'bantha' ? 17 : 31;
    const e = { x, y, type, angle: -0.35, phase: 0.7, hp: 10, maxHp: 10, slowT: 0, hitFlash: 0, radius };
    drawEnemy(ctx, e, 1.6, S);
  }
});
await page.waitForTimeout(300);
await page.screenshot({ path: 'screenshots/creatures.jpg', type: 'jpeg', quality: 88 });
await browser.close();
console.log('saved');

