  const hg = ctx.createLinearGradient(14, -6, 27, 6);
  hg.addColorStop(0, '#5c402a');
  hg.addColorStop(0.5, '#472f1f');
  hg.addColorStop(1, '#2e1d12');
  ctx.fillStyle = hg;
  ctx.beginPath();
  ctx.moveTo(15.2, -5.0);
  ctx.quadraticCurveTo(20.4, -6.4, 24.2, -4.8);
  ctx.lineTo(26.8, -2.3);
  ctx.quadraticCurveTo(27.8, 0, 26.8, 2.3);
  ctx.lineTo(24.2, 4.8);
  ctx.quadraticCurveTo(20.4, 6.4, 15.2, 5.0);
  ctx.quadraticCurveTo(14.2, 0, 15.2, -5.0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#201309';
  ctx.lineWidth = 0.9;
  ctx.stroke();
  // muzzle pad and nostrils
  ctx.fillStyle = 'rgba(166, 128, 90, 0.32)';
  ctx.beginPath();
  ctx.ellipse(23.6, 0, 3.0, 3.8, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#150c07';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(26.0, side * 1.3, 0.72, 0.42, side * 0.3, 0, TAU);
    ctx.fill();
  }
  ctx.strokeStyle = '#24150c';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(25.8, 0);
  ctx.quadraticCurveTo(26.8, 0, 27.0, 0);
  ctx.stroke();
  // eyes, deep-set under a brow
  for (const side of [-1, 1]) {
    ctx.fillStyle = 'rgba(24, 14, 8, 0.8)';
    ctx.beginPath();
    ctx.ellipse(20.8, side * 3.5, 1.55, 1.05, side * 0.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#0e0906';
    ctx.beginPath();
    ctx.arc(20.8, side * 3.5, 0.92, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 194, 102, 0.95)';
    ctx.beginPath();
    ctx.arc(20.95, side * 3.5, 0.31, 0, TAU);
    ctx.fill();
  }

  // Enormous ivory horns, sweeping out and curving forward around the
  // muzzle. They stay tapered so the silhouette does not become wings.
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.scale(1, side);
    const horn = ctx.createLinearGradient(17, 2, 35, 7);
    horn.addColorStop(0, '#8d714d');
    horn.addColorStop(0.34, '#b9a076');
    horn.addColorStop(0.68, '#e0cda6');
    horn.addColorStop(0.9, '#c9b087');
    horn.addColorStop(1, '#937750');
    ctx.fillStyle = horn;
    ctx.beginPath();
    ctx.moveTo(18.4, 5.7);
    ctx.bezierCurveTo(22.0, 8.4, 26.0, 9.6, 29.6, 9.4);
    ctx.bezierCurveTo(32.8, 9.2, 34.9, 7.8, 35.4, 5.5);
    ctx.bezierCurveTo(32.8, 4.6, 29.2, 4.8, 26.2, 4.2);
    ctx.bezierCurveTo(23.2, 3.6, 19.8, 2.8, 17.2, 2.2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#6a5336';
    ctx.lineWidth = 0.7;
    ctx.stroke();
    // growth rings
    ctx.strokeStyle = 'rgba(108, 82, 49, 0.4)';
    ctx.lineWidth = 0.45;
    for (let i = 0; i < 4; i++) {
      const bx = 21.0 + i * 3.1;
      ctx.beginPath();
      ctx.moveTo(bx, 8.7 - i * 0.28);
      ctx.quadraticCurveTo(bx + 0.9, 6.4 - i * 0.15, bx + 0.35, 4.1 + i * 0.12);
      ctx.stroke();
    }
