Tail plates block lines 3192-3216: replace whole loop. New:
```js
  // Segmented tail plates and a row of dorsal scutes.
  for (let i = 0; i < 7; i++) {
    const t = i / 6;
    const tx = -12.5 - t * 33.0;
    const ty = tailSwayB * (t * t * 7.2) + Math.sin(t * 2.8) * 0.8;
    const span = 4.4 * (1 - t * 0.72);
    ctx.strokeStyle = `rgba(91, 62, 36, ${0.22 + t * 0.16})`;
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(tx + 0.9, ty - span);
    ctx.quadraticCurveTo(tx - 0.6, ty, tx + 0.9, ty + span);
    ctx.stroke();
    const size = 2.2 * (1 - t * 0.55);
    const scute = ctx.createLinearGradient(tx - size, ty, tx + size, ty);
    scute.addColorStop(0, '#a8804d');
    scute.addColorStop(1, '#d0ab73');
    ctx.fillStyle = scute;
    ctx.beginPath();
    ctx.ellipse(tx, ty, size * 1.25, size * 0.9, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(75, 51, 30, 0.6)';
    ctx.lineWidth = 0.35;
    ctx.stroke();
  }
```
