// Crown horns: shorter, tan spikes that sweep back from behind the eyes
// instead of crossing the face.
for (const side of [-1, 1]) {
  ctx.save();
  ctx.scale(1, side);
  const horn = ctx.createLinearGradient(21, 4, 12, 11);
  horn.addColorStop(0, '#cbb18a');
  horn.addColorStop(0.55, '#b0946d');
  horn.addColorStop(1, '#856a49');
  ctx.fillStyle = horn;
  ctx.beginPath();
  ctx.moveTo(21.6, 4.8);
  ctx.bezierCurveTo(20.0, 8.2, 17.0, 10.4, 12.8, 11.3);
  ctx.bezierCurveTo(14.6, 8.4, 16.0, 6.0, 16.6, 3.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#60482e';
  ctx.lineWidth = 0.5;
  ctx.stroke();
  // small forward cheek spike, clear of the eye
  ctx.fillStyle = '#c3a67e';
  ctx.beginPath();
  ctx.moveTo(27.6, 4.9);
  ctx.bezierCurveTo(29.2, 7.0, 30.9, 7.6, 32.4, 7.0);
  ctx.bezierCurveTo(30.9, 5.7, 29.9, 4.5, 29.3, 3.1);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6c5236';
  ctx.lineWidth = 0.4;
  ctx.stroke();
  ctx.restore();
}
