ctx.bezierCurveTo(14.2, -5.4, 15.8, -2.6, 16.0, 0);
ctx.bezierCurveTo(15.8, 2.6, 14.2, 5.4, 10.8, 7.4);
ctx.bezierCurveTo(6.8, 9.8, 0.4, 9.2, -7.0, 8.8);
ctx.bezierCurveTo(-14.0, 8.4, -18.2, 5.6, -18.0, 0);
ctx.closePath();
ctx.fill();
ctx.strokeStyle = '#180e08';
ctx.lineWidth = 1.15;
ctx.stroke();

// Shaggy coat fringe: short, irregular clumps along the flanks and rump.
const furCols = ['rgba(96, 64, 41, 0.8)', 'rgba(58, 38, 24, 0.85)', 'rgba(132, 94, 61, 0.42)'];
for (let i = 0; i < 20; i++) {
  const a = 1.35 + (i / 19) * (TAU - 2.7);
  const bx = Math.cos(a) * 16.2;
  const by = Math.sin(a) * 8.7;
  const len = 0.9 + ((i * 5) % 4) * 0.35;
  const sweep = -0.4 + Math.sign(Math.cos(a)) * 0.22;
  ctx.strokeStyle = furCols[i % furCols.length];
  ctx.lineWidth = 1.25;
  ctx.beginPath();
  ctx.moveTo(bx * 0.95, by * 0.95);
  ctx.lineTo(bx + Math.cos(a + sweep) * len, by + Math.sin(a + sweep) * len);
  ctx.stroke();
}
// flowing coat strokes following the body
