// Crown horns: thick, tapered spikes sweeping back from behind the eyes.
for (const side of [-1, 1]) {
  ctx.save();
  ctx.scale(1, side);
  const pts = [[22.2, 4.6], [20.8, 8.6], [17.2, 11.4], [12.6, 12.8]];
  const widths = [4.4, 3.2, 1.6];
  // dark underlay gives the horn a clean silhouette
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#573d26';
  for (let i = 0; i < pts.length - 1; i++) {
    ctx.lineWidth = widths[i] + 1.0;
    ctx.beginPath();
    ctx.moveTo(pts[i][0], pts[i][1]);
    ctx.lineTo(pts[i + 1][0], pts[i + 1][1]);
    ctx.stroke();
  }
  const horn = ctx.createLinearGradient(22, 4, 12, 13);
  horn.addColorStop(0, '#c9ae86');
  horn.addColorStop(0.5, '#ddc8a0');
  horn.addColorStop(1, '#9a7c55');
  ctx.strokeStyle = horn;
  for (let i = 0; i < pts.length - 1; i++) {
    ctx.lineWidth = widths[i];
    ctx.beginPath();
    ctx.moveTo(pts[i][0], pts[i][1]);
    ctx.lineTo(pts[i + 1][0], pts[i + 1][1]);
    ctx.stroke();
  }
  // growth rings
  ctx.strokeStyle = 'rgba(96, 71, 43, 0.4)';
  ctx.lineWidth = 0.45;
  for (const [hx, hy] of [[21.2, 6.0], [19.4, 9.0], [16.8, 11.2]]) {
