input.newString:
// Enormous ivory horns: broad crescents that sweep out and forward from
// the skull, framing the head without crossing the muzzle.
for (const side of [-1, 1]) {
  ctx.save();
  ctx.scale(1, side);
  const horn = ctx.createLinearGradient(19, 3, 29, 13);
  horn.addColorStop(0, '#7f6544');
  horn.addColorStop(0.32, '#ab936b');
  horn.addColorStop(0.66, '#d6c199');
  horn.addColorStop(0.9, '#bfa67d');
  horn.addColorStop(1, '#8f734c');
  ctx.fillStyle = horn;
  ctx.beginPath();
  ctx.moveTo(18.6, 4.2);
  ctx.bezierCurveTo(21.4, 9.2, 24.8, 12.4, 28.8, 12.8);
  ctx.bezierCurveTo(26.8, 11.0, 24.6, 9.8, 23.0, 8.2);
  ctx.bezierCurveTo(21.4, 6.6, 19.8, 4.8, 18.6, 2.2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6a5336';
  ctx.lineWidth = 0.6;
  ctx.stroke();
  // growth rings
  ctx.strokeStyle = 'rgba(104, 79, 47, 0.4)';
  ctx.lineWidth = 0.4;
  for (let i = 0; i < 3; i++) {
    const t = 0.2 + i * 0.26;
    const bx = 19.8 + t * 8.4;
    const by = 4.6 + t * 7.4;
    ctx.beginPath();
    ctx.moveTo(bx - 0.8, by - 1.4);
    ctx.lineTo(bx + 0.8, by + 1.6);
    ctx.stroke();
  }
  // polished outer edge
  ctx.strokeStyle = 'rgba(255, 246, 219, 0.5)';
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(19.8, 6.2);
  ctx.quadraticCurveTo(24.6, 12.2, 28.4, 12.6);
  ctx.stroke();
  ctx.restore();
}

