    ctx.fillStyle = '#715234';
    ctx.beginPath();
    ctx.ellipse(leg.kx + swing * 0.3, leg.ky, 4.4, 3.8, 0, 0, TAU);
    ctx.fill();
    // lower limb
    ctx.strokeStyle = '#967247';
    ctx.lineWidth = 5.6;
    ctx.beginPath();
    ctx.moveTo(leg.kx + swing * 0.3, leg.ky);
    ctx.lineTo(leg.ax + swing * 0.65, leg.ay);
    ctx.stroke();
