  ctx.bezierCurveTo(4.0, -12.3, 13.0, -10.6, 17.0, -6.8);
  ctx.bezierCurveTo(19.0, -4.2, 19.0, 4.2, 17.0, 6.8);
  ctx.bezierCurveTo(13.0, 10.6, 4.0, 12.3, -4.0, 11.5);
